package com.bestpractice.api.domain;

import org.junit.jupiter.api.BeforeAll;
import static org.junit.jupiter.api.Assertions.assertThrows;
import org.junit.jupiter.api.extension.ExtendWith;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.security.crypto.password.PasswordEncoder;

import static org.junit.jupiter.api.Assertions.*;

public class DomainBeanGeneratedAiTests {

    private DomainBean domainBean;

    @BeforeEach
    void setUp() {
        domainBean = new DomainBean();
    }

    @Test
    void testPasswordEncoderNotNull() {
        // GIVEN - a DomainBean instance
        // WHEN - calling passwordEncoder method
        PasswordEncoder encoder = domainBean.passwordEncoder();
        // THEN - the returned PasswordEncoder should not be null
        assertNotNull(encoder);
    }

    @Test
    void testPasswordEncoderEncodesPasswordCorrectly() {
        // GIVEN - a DomainBean instance and a raw password
        String rawPassword = "testPassword";
        PasswordEncoder encoder = domainBean.passwordEncoder();
        // WHEN - encoding the raw password
        String encodedPassword = encoder.encode(rawPassword);
        // THEN - the encoded password should not match the raw password and should be valid
        assertNotEquals(rawPassword, encodedPassword);
        assertTrue(encoder.matches(rawPassword, encodedPassword));
    }

    @Test
    void testPasswordEncoderMatchesReturnsFalseForDifferentPassword() {
        // GIVEN - a DomainBean instance and a raw password
        String rawPassword = "testPassword";
        PasswordEncoder encoder = domainBean.passwordEncoder();
        String encodedPassword = encoder.encode(rawPassword);
        // WHEN - checking match with a different password
        boolean matches = encoder.matches("differentPassword", encodedPassword);
        // THEN - matches should be false
        assertFalse(matches);
    }
}

